-- -*- mode: lua -*-

-- MIDI map for the AKAI MIDIMIX. Albert Gräf <agggraef@gmail.com>, 2024

-- To use this, load this map in Raptor, connect the MIDIMIX to Pd's second
-- MIDI input, and you should be set.

-- This is similar to the Launch Control XL map. The mapping of the knobs,
-- faders, and the two button rows is virtually the same, although the CC and
-- note numbers differ (please check the launchcontrol.map file for a more
-- detailed explanation of the layout).

-- KNOBS AND FADERS:

-- [minvel] [pmin] [wmin] [gate]    [hmin]  [pref]    [smin]  [uniq]
-- [maxvel] [pmax] [wmax] [gate]    [hmax]  [pref]    [smax]  [nmax]
-- [velmod] [pmod] [gain] [gatemod] [hmod]  [prefmod] [smod]  [nmod]

-- [hi]     [lo]   [mode] [pos]     [tempo] [num]     [denom] [divis]

-- BUTTON ROWS:

--   - voice controls -                       - looper controls -
-- [mute] [latch] [bypass]  [      ] [      ] [load] [save] [loop]
-- [    ] [     ] [raptor]  [rewind] [      ] [prev] [next] [play]

-- In addition, the BANK LEFT/RIGHT buttons on the right are available as
-- alternative bindings for the looper controls (loop prev, next).

-- HARD-WRIRED BINDINGS (select a Raptor ccmaster instance): SOLO + BANK
-- LEFT/RIGHT cycles through the Raptor instances, SOLO + 1-8 selects or
-- deselects one of the first 8 instances.

{
  -- panel controls (knobs)
  [16] = { [17] = "minvel" },
  [17] = { [17] = "maxvel" },
  [18] = { [17] = "velmod" },
  [20] = { [17] = "pmin" },
  [21] = { [17] = "pmax" },
  [22] = { [17] = "pmod" },
  [24] = { [17] = "wmin" },
  [25] = { [17] = "wmax" },
  [26] = { [17] = "gain" },
  [28] = { [17] = "gate" },
  [29] = { [17] = "gate" },
  [30] = { [17] = "gatemod" },
  [46] = { [17] = "hmin" },
  [47] = { [17] = "hmax" },
  [48] = { [17] = "hmod" },
  [50] = { [17] = "pref" },
  [51] = { [17] = "pref" },
  [52] = { [17] = "prefmod" },
  [54] = { [17] = "smin" },
  [55] = { [17] = "smax" },
  [56] = { [17] = "smod" },
  [58] = { [17] = "uniq" },
  [59] = { [17] = "nmax" },
  [60] = { [17] = "nmod" },
  -- faders
  [19] = { [17] = "pitchhi" },
  [23] = { [17] = "pitchlo" },
  [27] = { [17] = "mode" },
  [31] = { [17] = "pos" },
  [49] = { [17] = "tempo" },
  [53] = { [17] = "meter-num" },
  [57] = { [17] = "meter-denom" },
  [61] = { [17] = "division" },
  -- upper button row
  [129] = { [17] = { "mute", true } },
  [132] = { [17] = { "latch", true } },
  [135] = { [17] = { "bypass", true } },
  [144] = { [17] = { "loop-load", true } },
  [147] = { [17] = { "loop-save", true } },
  [150] = { [17] = { "loop", true } },
  -- lower button row
  [137] = { [17] = { "raptor", true } },
  [140] = { [17] = { "rewind", true } },
  [146] = { [17] = { "loop-prev", true } },
  [149] = { [17] = { "loop-next", true } },
  [152] = { [17] = { "play", true } },
  -- BANK LEFT/RIGHT buttons: alternative bindings for loop prev and next
  [153] = { [17] = { "loop-prev", true } },
  [154] = { [17] = { "loop-next", true } },
}
